-- V132 NATAL ESTELAR. Execute before deploying the matching ZIP. Additive, no player deletion.
BEGIN;
CREATE TABLE IF NOT EXISTS public.stellar_natal_config_v132(id int PRIMARY KEY CHECK(id=1), enabled boolean NOT NULL DEFAULT true, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, goals jsonb NOT NULL);
INSERT INTO public.stellar_natal_config_v132 SELECT 1,true,'2026-11-07 03:00Z','2027-01-06 03:00Z',
 jsonb_object_agg(f, jsonb_build_object('players',n,'npc',jsonb_build_array(n*150,n*400,n*900),'box',jsonb_build_array(n*80,n*200,n*450)))
 FROM (SELECT f,greatest(1,count(s.user_id)) n FROM unnest(ARRAY['earth','mars','jupiter']) f LEFT JOIN public.game_saves s ON s.state#>>'{profile,faction}'=f AND s.updated_at>now()-interval '14 days' GROUP BY f) t ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.stellar_natal_players_v132(user_id uuid PRIMARY KEY, faction text NOT NULL, npc bigint NOT NULL DEFAULT 0, box bigint NOT NULL DEFAULT 0, boss bigint NOT NULL DEFAULT 0, fireworks int NOT NULL DEFAULT 0, last_firework timestamptz);
CREATE TABLE IF NOT EXISTS public.stellar_natal_actions_v132(user_id uuid NOT NULL, key text NOT NULL, receipt jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS public.stellar_natal_counts_v132(key text PRIMARY KEY,faction text NOT NULL,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS natal_counts_kind_idx ON public.stellar_natal_counts_v132(faction,kind);
CREATE TABLE IF NOT EXISTS public.stellar_natal_rewards_v132(id text PRIMARY KEY,definition jsonb NOT NULL);
ALTER TABLE public.stellar_natal_config_v132 ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.stellar_natal_config_v132 FROM PUBLIC,anon,authenticated; GRANT ALL ON public.stellar_natal_config_v132 TO service_role;
ALTER TABLE public.stellar_natal_players_v132 ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.stellar_natal_players_v132 FROM PUBLIC,anon,authenticated; GRANT ALL ON public.stellar_natal_players_v132 TO service_role;
ALTER TABLE public.stellar_natal_actions_v132 ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.stellar_natal_actions_v132 FROM PUBLIC,anon,authenticated; GRANT ALL ON public.stellar_natal_actions_v132 TO service_role;
ALTER TABLE public.stellar_natal_counts_v132 ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.stellar_natal_counts_v132 FROM PUBLIC,anon,authenticated; GRANT ALL ON public.stellar_natal_counts_v132 TO service_role;
ALTER TABLE public.stellar_natal_rewards_v132 ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.stellar_natal_rewards_v132 FROM PUBLIC,anon,authenticated; GRANT ALL ON public.stellar_natal_rewards_v132 TO service_role;
